      !safeInteger(value.moves) || value.moves > MAX_MOVES || !safeInteger(value.elapsedMs) ||
      value.elapsedMs > MAX_ELAPSED_MS || typeof value.started !== 'boolean') return null;
  const state = createGame(value.boardCode);
