import { createGame } from './state.ts';
import { activateCard, advanceGame } from './transitions.ts';
import type { GameState } from './state.ts';

const REPLAY_LIMIT = 1_048_576;
const ACTION_LIMIT = 10_000;
type ReplayAction = Readonly<{ atMs: number; index: number }>;
type Replay = Readonly<{ version: 1; boardCode: string; actions: readonly ReplayAction[]; endMs: number }>;
type UnknownRecord = Record<string, unknown>;

function record(value: unknown): value is UnknownRecord {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function hasKeys(value: UnknownRecord, keys: readonly string[]): boolean {
  return Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key));
}

function isTime(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

function parseReplay(value: unknown): Replay | null {
  if (!record(value) || !hasKeys(value, ['version', 'boardCode', 'actions', 'endMs']) || value.version !== 1 ||
      typeof value.boardCode !== 'string' || !Array.isArray(value.actions) || value.actions.length > ACTION_LIMIT ||
      !isTime(value.endMs)) return null;
  const actions: ReplayAction[] = [];
  let previous = 0;
  for (const item of value.actions) {
    if (!record(item) || !hasKeys(item, ['atMs', 'index']) || !isTime(item.atMs) || !isTime(item.index) ||
        item.atMs < previous) return null;
    previous = item.atMs;
    actions.push({ atMs: item.atMs, index: item.index });
  }
  if (actions.length > 0 && value.endMs < previous) return null;
  return { version: 1, boardCode: value.boardCode, actions, endMs: value.endMs };
}

export function runReplay(replay: Replay): GameState | null {
  let state = createGame(replay.boardCode);
  if (state === null) return null;
  let previous = 0;
  for (const action of replay.actions) {
    if (action.index >= state.board.deck.length) return null;
    state = advanceGame(state, action.atMs - previous);
    state = activateCard(state, action.index);
    previous = action.atMs;
  }
  return advanceGame(state, replay.endMs - previous);
}

export function replayGame(text: string): GameState | null {
  if (new TextEncoder().encode(text).length > REPLAY_LIMIT) return null;
  try {
    const replay = parseReplay(JSON.parse(text) as unknown);
    return replay === null ? null : runReplay(replay);
  } catch { return null; }
}
export const GRID_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
const MODULUS = 2_147_483_647;
const GENERATOR = 16_807;
const DRAW_RANGE = MODULUS - 1;

export type GridSize = (typeof GRID_SIZES)[number];
export type Board = Readonly<{ boardCode: string; side: GridSize; deck: readonly number[] }>;
export type BoardCode = Readonly<{ boardCode: string; side: GridSize; seed: number }>;

const isGridSize = (value: number): value is GridSize =>
  GRID_SIZES.some((size) => size === value);

export function parseBoardCode(input: string): BoardCode | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(input);
  if (match === null || match[0] !== input) return null;
  const sideText = match[1];
  const seedText = match[2];
  if (sideText === undefined || seedText === undefined) return null;
  const side = Number(sideText);
  const seed = Number(seedText);
  if (!isGridSize(side) || !Number.isSafeInteger(seed) || seed > DRAW_RANGE) return null;
  return { boardCode: input, side, seed };
}

function nextState(state: number): number {
  return (state * GENERATOR) % MODULUS;
}

function drawIndex(state: number, bound: number): Readonly<{ state: number; index: number }> {
  const limit = Math.floor(DRAW_RANGE / bound) * bound;
  let current = state;
  let value = 0;
  do {
    current = nextState(current);
    value = current - 1;
  } while (value >= limit);
  return { state: current, index: value % bound };
}

export function generateBoard(code: BoardCode): Board {
  const count = code.side * code.side;
  const deck = Array.from({ length: count }, (_, index) => Math.floor(index / 2));
  let state = code.seed;
  for (let index = count - 1; index > 0; index -= 1) {
    const draw = drawIndex(state, index + 1);
    state = draw.state;
    const value = deck[index];
    const other = deck[draw.index];
    if (value !== undefined && other !== undefined) {
      deck[index] = other;
      deck[draw.index] = value;
    }
  }
  return { boardCode: code.boardCode, side: code.side, deck };
}
