    if (viewport.width === 1280) await current.screenshot({ path: 'evidence/neon-pairs-desktop.png', fullPage: true });
    if (viewport.width === 640) await current.screenshot({ path: 'evidence/neon-pairs-zoom-equivalent.png', fullPage: true });
